mapper.select:
WITH tmp AS ( SELECT CASH_ID, ACCR_TDAY_RULE from FIN_FLOAT_COUNTING_RULE GROUP BY CASH_ID, ACCR_TDAY_RULE ) SELECT * FROM ( SELECT info.cash_id cashId,/**/ info.finprod_id finprodId,/**/ info.finprod_type finprodType,/**/ info.cash_type_1 cashType1,/*现金流一级类型，本金、利息、费用 */ info.cash_type_1 cashType1Code,/*现金流一级类型，本金、利息、费用 */ info.cash_type_2 cashType2,/*现金流二级类型，本金、利息、托管费、固定管理费、浮动管理费等 */ info.cash_type_2 cashType2Code,/*现金流二级类型，本金、利息、托管费、固定管理费、浮动管理费等 */ to_char(crule.eff_date, 'yyyy-MM-dd') effDate,/*生效日期 */ crule.calc_type calcType,/*计算类型，固定利率、浮动利率 */ crule.calc_type calcTypeCode,/*计算类型，固定利率、浮动利率 */
crule.yield * 100 yield,/*生效利率 */ crule.basis,/*计息基础，a/360，a/365等 */ crule.base_type baseType,/*基数类型 */ crule.base_type baseTypeCode,/*基数类型 */ crule.base_date_type baseDateType,/*基数日期类型，上一工作日、上一自然日、当日、上一开放日等 */ crule.base_date_type baseDateTypeCode,/*基数日期类型，上一工作日、上一自然日、当日、上一开放日等 */ prule.pay_cycle payCycle,/*支付频率 */ prule.pay_cycle payCycleCode,/*支付频率 */
prule.END_TDAY_RULE endTdayRule, /*付费截止日营业日准则 */ prule.END_TDAY_RULE endTdayRuleCode, /*付费截止日营业日准则 code*/ prule.PAY_TDAY_RULE payTdayRule, /*付费支付日营业日准则 */ prule.PAY_TDAY_RULE payTdayRuleCode, /*付费支付日营业日准则 code*/ prule.calc_rule calcRule,/*推算方式 */ prule.calc_rule calcRuleCode,/*推算方式 */ to_char(prule.first_pay_date, 'yyyy-MM-dd') firstPayDate,/*首次支付日 */ prule.cash_unit_type cashUnitType,/*现金流单位，百元法、总额法 */ prule.cash_unit_type cashUnitTypeCode,/*现金流单位，百元法、总额法 */ prule.pay_type payType, /*支付方式，现金、红利再投等 */ prule.pay_type payTypeCode, /*支付方式，现金、红利再投等 */ crule.remark, A.ACCR_TDAY_RULE as accrTdayRule,/** 计费营业日准则 **/
ROW_NUMBER() OVER( PARTITION BY crule.CASH_ID, crule.FINPROD_ID, crule.FINPROD_TYPE ORDER BY crule.EFF_DATE ASC) AS rn1, ROW_NUMBER() OVER( PARTITION BY prule.CASH_ID, prule.FINPROD_ID, prule.FINPROD_TYPE ORDER BY crule.EFF_DATE ASC) AS rn2 FROM FIN_CASH_INFO info LEFT JOIN fin_cash_calc_rule crule ON info.cash_id = crule.cash_id AND info.finprod_id = crule.finprod_id AND info.finprod_type = crule.finprod_type LEFT JOIN fin_cash_pay_rule prule ON info.cash_id = prule.cash_id AND info.finprod_id = prule.finprod_id AND info.finprod_type = prule.finprod_type LEFT JOIN tmp A ON A.CASH_ID = info.CASH_ID WHERE info.cash_type_1 = '03'
AND info.FINPROD_id = #{finprodId}
AND info.cash_type_2 = #{cashType2}
AND info.cash_type_2 != #{noCashType2}
) WHERE rn1 = 1 AND rn2 = 1

select acct.acct_no acctNo, acct.acct_type acctType, acct.acct_type acctTypeCode, acct.finprod_id finprodId, acct.finprod_type finprodType, acct.finprod_type finprodTypeCode, acct.ccy, acct.ccy ccyCode, info.acct_name acctName, info.bank_dep bankDep, info.corr_no corrNo, info.large_payno largePayno, info.bln_area blnArea, info.bln_area blnAreaCode,
'' bankDepType, '' bankDepTypeCode, '' customerName, info.swift_code swiftCode from Stl_Fin_Product_Acct acct left join stl_capacct_info info on acct.acct_no = info.acct_no
where 1=1
AND acct.FINPROD_TYPE = #{finprodType}
AND acct.FINPROD_id = #{finprodId}

select '' feeName, /*费用名称 */ crule.base_type baseType, /*计费基数 */ crule.basis basis, /*计息基础 */ ffcr2.BASE_RULE calcRule, /*计算规则 */ ffcr2.BASE_RULE calcRuleCode, TO_CHAR(ffcr.f_accr_date, 'yyyy-MM-dd') firCalculaDate, /*首次计提日*/ TO_CHAR(TMP.ACCR_END_DATE, 'yyyy-MM-dd') endCalculaDate, /*计提结束日 */ TO_CHAR(ffas.accr_str_date, 'yyyy-MM-dd') jtStrDate, /*计提周期开始日 */ TO_CHAR(ffas.accr_end_date, 'yyyy-MM-dd') jtEndDate, /*计提周期结束日 */ TO_CHAR(ffas.accr_date, 'yyyy-MM-dd') jtDate, /*计提日 */ C.LEV AS basicLevel, /*业绩比较基准层级 */ '' AS levelRemark, /*层级描述 */ C.CHARGE_RATIO AS bankRatio, /*银行收取比例 */ NVL2(C.CHARGE_RATIO, 1 - C.CHARGE_RATIO, '') AS customerRatio, /*客户分配比例 */ ffcr2.ACT_RULE actRule, /*生效规则 */ prule.pay_type payType, /*付费规则 */ prule.pay_type payTypeCode, /*付费规则code */ ffcr.ACCR_TDAY_RULE accrTdayRule, /*计费营业日准则 */
prule.END_TDAY_RULE endTdayRule, /*付费截止日营业日准则 */ prule.END_TDAY_RULE endTdayRuleCode, /*付费截止日营业日准则 code*/ prule.PAY_TDAY_RULE payTdayRule, /*付费支付日营业日准则 */ prule.PAY_TDAY_RULE payTdayRuleCode, /*付费支付日营业日准则 code*/ '' vdate, /*计费开始日*/ '' mdate, /*计费结束日*/ '' paydate /*支付日*/ from fin_cash_info fci left join fin_cash_calc_rule crule on fci.cash_id = crule.cash_id LEFT JOIN fin_cash_pay_rule prule ON crule.cash_id = prule.cash_id AND crule.EFF_DATE = prule.EFF_DATE LEFT JOIN FIN_FLOAT_COUNTING_RULE ffcr ON crule.cash_id = ffcr.cash_id AND crule.EFF_DATE = ffcr.EFF_DATE LEFT JOIN FIN_FLOAT_CALC_RULE_DETAIL C ON C.CASH_ID = ffcr.CASH_ID AND C.EFF_DATE = ffcr.EFF_DATE LEFT JOIN FIN_FLOAT_ACCRUAL_SCHE ffas ON ffas.cash_id = ffcr.cash_id LEFT JOIN FIN_FLOAT_CALC_RULE ffcr2 ON ffcr2.cash_id = ffcr.cash_id LEFT JOIN ( SELECT CASH_ID,MAX(ACCR_END_DATE) ACCR_END_DATE FROM FIN_FLOAT_ACCRUAL_SCHE GROUP BY CASH_ID ) TMP ON TMP.CASH_ID = fci.CASH_ID where 1=1
AND crule.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}
order by jtStrDate asc

select TO_CHAR(ffas.accr_str_date, 'yyyy-MM-dd') jtStrDate, /*计提周期开始日 */ TO_CHAR(ffas.accr_end_date, 'yyyy-MM-dd') jtEndDate, /*计提周期结束日 */ TO_CHAR(ffas.accr_date, 'yyyy-MM-dd') jtDate /*计提日 */ from fin_cash_info fci LEFT JOIN FIN_FLOAT_ACCRUAL_SCHE ffas ON ffas.cash_id = fci.cash_id where 1=1
AND fci.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}
order by ffas.accr_str_date asc

select C.LEV AS basicLevel, /*业绩比较基准层级 */ '' AS levelRemark, /*层级描述 */ C.CHARGE_RATIO AS bankRatio, /*银行收取比例 */ NVL2(C.CHARGE_RATIO, 1 - C.CHARGE_RATIO, '') AS customerRatio /*客户分配比例 */ from fin_cash_info fci LEFT JOIN ( SELECT CASH_ID,MAX(EFF_DATE) MAX_EFF_DATE FROM FIN_FLOAT_CALC_RULE GROUP BY CASH_ID ) TMP ON TMP.CASH_ID = fci.CASH_ID LEFT JOIN FIN_FLOAT_CALC_RULE_DETAIL C ON C.CASH_ID = TMP.CASH_ID AND C.EFF_DATE = TMP.MAX_EFF_DATE where 1=1
AND fci.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}
order by C.LEV asc

	SELECT paramValue from (select row_number() over() rownum,
    PARAM_VALUE AS paramValue
	FROM BOK_BOOKSET_EXT 
	WHERE
	PARAM_CODE=#{paramCode}
	and BOOKSET_ID = #{finprodId}
	)where rownum=1
